# R-cell form Q0^N - K_R^N for a generalized-integer system N (window length log R fixed).
# N = multiplicatively closed set generated by real generators g > 1 (as a SET; Lambda_N solved from Lambda_N * 1_N = log on N).
# Q^N = Tm^T (Arch - Pi_N) Tm + a b^T + b a^T,  Tm = sum_{x in N, x<R} x^{-1/2} tau_{log x},  Pi_N = sum 2 Lambda_N(x) x^{-1/2} c^sym(log x).
# Constraints: f0, flam (system-free) and A, B built from the summation set S (S = Z: integers;  S = N: the system).
# Gauge form L reused from the cached Z-split pickle (system-free).  usage: R Nb T J dps SYS CON [eps]
#  SYS: 'pow:t' (p -> p^(1+t)) | 'powfix:t' (same, window index set kept = {n<R}) | 'nat' | 'gens:2.05,3.1' (replace primes 2,3; others kept) | 'add:2.5' | 'only:2,3' | 'root2' (sqrt p) | 'natsqrt2' (N u sqrt2 N)
#  CON: 'Z' | 'N' | 'S:<spec>' (summation set of another system)
import sys, os, time, pickle, mpmath as mp
sys.path.insert(0,'/home/trabajo/Documentos/research/riemann/03-research/phase-211-sign-sandbox/tools')
import galerkin_mp as Gm
R=int(sys.argv[1]); Nb=int(sys.argv[2]); Ts=sys.argv[3]; T=mp.mpf(Ts); J=int(sys.argv[4]); dps=int(sys.argv[5])
SYS=sys.argv[6]; CON=sys.argv[7]; NQ=160
mp.mp.dps=dps; t0=time.time()
base=pickle.load(open(f"/tmp/phase211/r21/split_{R}_{Nb}_{Ts}_{J}_{dps}_{NQ}.pkl",'rb'))
tm=lambda rows: mp.matrix([[mp.mpf(x) for x in r] for r in rows])
C0=tm(base['C']); L=tm(base['L'])
BOUND=60
primes=[p for p in range(2,BOUND) if Gm._Lam(p)==p]
def gens_of(s):
    if s=='nat': return [mp.mpf(p) for p in primes]
    k,arg=s.split(':') if ':' in s else (s,'')
    if k=='gens':
        new=[mp.mpf(x) for x in arg.split(',')]; g=[mp.mpf(p) for p in primes]
        for i,x in enumerate(new): g[i]=x
        return g
    if k=='add': return [mp.mpf(p) for p in primes]+[mp.mpf(x) for x in arg.split(',')]
    if k=='only': return [mp.mpf(x) for x in arg.split(',')]
    if k=='root2': return [mp.sqrt(p) for p in primes]+[mp.sqrt(p) for p in range(BOUND,BOUND*BOUND) if Gm._Lam(p)==p and p<BOUND*BOUND][:0]
    if k in('pow','powfix'): return [mp.mpf(p)**(1+mp.mpf(arg)) for p in primes]
    if k=='natsqrt2': return [mp.mpf(p) for p in primes]+[mp.sqrt(2)]
    if k=='scale': # all primes p -> p^(1+eps)? kept for first variation: gens:... used instead
        pass
# split of the exponent direction: pow:t = positions x=n^(1+t), weights x^(-1/2), Lambda_N=(1+t)Lambda.
#  sig:t positions n, weights n^(-(1+t)/2);  pos:t positions n^(1+t), weights n^(-1/2), Lambda;  lam:t positions n, Lambda*(1+t).
_k=SYS.split(':')[0]; _t=mp.mpf(SYS.split(':')[1]) if _k in('sig','pos','lam') else mp.mpf(0)
WEXP={'sig':(1+_t)/2,'pos':1/(2*(1+_t))}.get(_k,mp.mpf(1)/2); LFAC={'pos':1/(1+_t),'lam':1+_t}.get(_k,mp.mpf(1))
gens=gens_of('pow:'+SYS.split(':')[1] if _k=='pos' else ('nat' if _k in('sig','lam') else SYS))
key=lambda x: mp.nstr(x,25)
Nset={key(mp.mpf(1)):mp.mpf(1)}
frontier=[mp.mpf(1)]
while frontier:
    nf=[]
    for x in frontier:
        for g in gens:
            y=x*g
            if y<BOUND and key(y) not in Nset: Nset[key(y)]=y; nf.append(y)
    frontier=nf
els=sorted(Nset.values())
idx={key(x):i for i,x in enumerate(els)}
Lam={}
for x in els[1:]:
    s=mp.mpf(0)
    for d in els[1:]:
        if d>=x: break
        e=x/d; k=key(e)
        if k in idx and d in () : pass
        if k in idx and key(d) in Lam: s+=Lam[key(d)]
    Lam[key(x)]=mp.log(x)-s
Rcut=mp.mpf(R)**(1+mp.mpf(SYS.split(':')[1])) if SYS.startswith('powfix') else R
win=[x for x in els if x<Rcut*(1-mp.mpf(10)**(-20))]  # powfix: same index set n<R (no cell enters/leaves)
print('SYS',SYS,'elements<R',[mp.nstr(x,6) for x in win],flush=True)
print('Lambda<R',[(mp.nstr(x,5),mp.nstr(Lam[key(x)],5)) for x in win[1:] if abs(Lam[key(x)])>mp.mpf(10)**(-dps//2)],flush=True)
ell=mp.log(R); h=ell/2; L_=2*h
Dd=Gm.build(h,Nb,dps=dps,verbose=False,cache=True,errcheck=False); mp.mp.dps=dps
Arch=Dd['Arch']; al=[k*mp.pi/L_ for k in range(1,Nb+1)]
Pi=mp.matrix(Nb,Nb)
for x in win[1:]:
    lv=Lam[key(x)]
    if abs(lv)<mp.mpf(10)**(-dps//2): continue
    v=2*lv*LFAC*x**(-WEXP)
    for j in range(1,Nb+1):
        for k in range(j,Nb+1):
            c=v*Gm._c_sym(j,k,mp.log(x),L_,al); Pi[j-1,k-1]+=c
            if k!=j: Pi[k-1,j-1]+=c
from flint import arb, ctx
ctx.prec=int(mp.mp.prec)+20
GLn=[(mp.mpf(x.mid().str(mp.mp.dps+5,radius=False)),mp.mpf(w.mid().str(mp.mp.dps+5,radius=False))) for x,w in (arb.legendre_p_root(NQ,k,weight=True) for k in range(NQ))]
qn=lambda a,b: [((a+b)/2+(b-a)/2*x,(b-a)/2*w) for x,w in GLn]
e=lambda k,z: mp.sin(k*mp.pi*(z+h)/ell)/mp.sqrt(h)
Tm=mp.matrix(Nb,Nb)
for N in win:
    lN=mp.log(N)
    for z,w in qn(-h+lN,h):
        Ei=[e(k,z) for k in range(1,Nb+1)]; Ej=[e(k,z-lN) for k in range(1,Nb+1)]
        c=w*N**(-WEXP)
        for i in range(Nb):
            for j in range(Nb): Tm[i,j]+=c*Ei[i]*Ej[j]
ZN=qn(-h,h); EZ=[[e(k,z) for k in range(1,Nb+1)] for z,w in ZN]
def proj(fn):
    v=mp.matrix(Nb,1)
    for (z,w),Ez in zip(ZN,EZ):
        fz=fn(z)*w
        for k in range(Nb): v[k]+=Ez[k]*fz
    return v
lam=mp.exp(T); xw=lambda z: z-T-h
a_=Tm.T*proj(lambda z: mp.exp(xw(z)/2)); b_=Tm.T*proj(lambda z: mp.exp(-xw(z)/2))
C=C0.copy()
def els_of(spec):
    gg=gens_of(spec); S_={key(mp.mpf(1)):mp.mpf(1)}; fr=[mp.mpf(1)]
    while fr:
        nf=[]
        for x in fr:
            for g in gg:
                y=x*g
                if y<BOUND and key(y) not in S_: S_[key(y)]=y; nf.append(y)
        fr=nf
    return sorted(S_.values())
if CON!='Z':
    ns=[x for x in (els if CON=='N' else els_of(CON[2:])) if x*mp.exp(-T)<lam]
    def I_(xi,a,b): return 2*(mp.sin(2*mp.pi*xi*b)-mp.sin(2*mp.pi*xi*a))/(2*mp.pi*xi)
    def Il(xi,a,b): return 2*(mp.ci(2*mp.pi*xi*b)-mp.ci(2*mp.pi*xi*a))
    fA=lambda z: mp.sqrt(mp.exp(-xw(z)))*mp.fsum(I_(mp.exp(-xw(z)),n*mp.exp(-T),min(n*mp.exp(T),lam))/n for n in ns)
    fB=lambda z: mp.sqrt(mp.exp(-xw(z)))*mp.fsum(Il(mp.exp(-xw(z)),n*mp.exp(-T),min(n*mp.exp(T),lam)) for n in ns)
    vA=proj(fA); vB=proj(fB)
    for j in range(Nb): C[j,2]=vA[j]; C[j,3]=vB[j]
Q0=Tm.T*Arch*Tm+a_*b_.T+b_*a_.T; K=Tm.T*Pi*Tm
Qf,_=mp.qr(C,mode='full'); V=Qf[:,4:Nb]; sym=lambda M:(M+M.T)/2
A0=sym(V.T*Q0*V); AK=sym(V.T*K*V); Lv=sym(V.T*L*V); Li=mp.inverse(mp.cholesky(Lv))
M=A0-AK
E,U=mp.eigsy(M); i0=min(range(len(E)),key=lambda i:E[i]); u=U[:,i0]
e2=min(mp.eigsy(sym(Li*M*Li.T),eigvals_only=True))
print(f"RES R={R} T={Ts} SYS={SYS} CON={CON}: bottom Q/|F|^2 {mp.nstr(E[i0],5)}  Q/l_g {mp.nstr(e2,5)}  K[u] {mp.nstr((u.T*AK*u)[0],4)}  Q0[u] {mp.nstr((u.T*A0*u)[0],4)}  t={round(time.time()-t0)}s",flush=True)
if os.environ.get('EIGS'):
    srt=sorted(range(len(E)),key=lambda i:E[i])[:4]
    print('EIGS',SYS,[mp.nstr(E[i],25) for i in srt],flush=True)
if os.environ.get('SAVE'):  # dump the V_R matrix of the form (for linearised edge predictions)
    pickle.dump({'M':[[mp.nstr(M[i,j],dps) for j in range(M.cols)] for i in range(M.rows)],'Lv':[[mp.nstr(Lv[i,j],dps) for j in range(Lv.cols)] for i in range(Lv.rows)]},open(f"/tmp/phase211/r23/M_{R}_{Ts}_{SYS}.pkl",'wb'))
